package com.example.simpleclient;
import com.fasterxml.jackson.databind.*;import javafx.application.Platform;import javafx.fxml.FXML;import javafx.scene.control.Label;import java.net.URI;import java.net.http.*;
public class AdminReportsController{@FXML private Label revenueLabel,bookingsLabel,customersLabel,activeLabel,paidLabel,carsLabel,statusLabel;private final HttpClient h=HttpClient.newHttpClient();private final ObjectMapper m=new ObjectMapper();@FXML private void initialize(){refresh();}@FXML private void refresh(){new Thread(()->{try{HttpRequest r=HttpRequest.newBuilder(URI.create("http://localhost:8080/api/admin/summary")).header("Authorization","Bearer "+AdminSession.getToken()).GET().build();JsonNode j=m.readTree(h.send(r,HttpResponse.BodyHandlers.ofString()).body());Platform.runLater(()->{revenueLabel.setText(String.format("RM %.2f",j.path("revenue").asDouble()));bookingsLabel.setText(j.path("bookings").asText());customersLabel.setText(j.path("customers").asText());activeLabel.setText(j.path("activeRentals").asText());paidLabel.setText(j.path("paidBookings").asText());carsLabel.setText(j.path("cars").asText());statusLabel.setText("Live operational summary");});}catch(Exception e){Platform.runLater(()->statusLabel.setText("Unable to load report"));}}).start();}}
